package cl.nexbyte.siger.custodia;
import java.io.*;import java.nio.file.*;import java.nio.file.attribute.*;import java.util.*;
import tools.jackson.databind.json.JsonMapper;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;

class AgentePortabilidadTest {
 @TempDir Path temp;
 @Test void canalAnonimoConsumeSecretoSinArchivoNiArgumento()throws Exception{var p=new Properties();AgenteCustodiaNativo.secretos(p,new ByteArrayInputStream("{\"usuario\":\"aplicacion-sintetica\",\"password\":\"SOLO-MEMORIA-SINTETICO\"}".getBytes(java.nio.charset.StandardCharsets.UTF_8)),JsonMapper.builder().build());assertEquals("aplicacion-sintetica",p.getProperty("garantia.origen.db.user"));assertEquals("SOLO-MEMORIA-SINTETICO",p.getProperty("garantia.origen.db.password"));try(var entries=Files.list(temp)){assertEquals(0,entries.count());}}
 @Test void rechazaSecretoPersistenteOTramaExcesiva()throws Exception{var p=new Properties();p.setProperty("garantia.origen.db.password","persistente-sintetico");assertThrows(IOException.class,()->AgenteCustodiaNativo.secretos(p,new ByteArrayInputStream("{\"usuario\":\"a\",\"password\":\"b\"}".getBytes()),JsonMapper.builder().build()));assertThrows(IOException.class,()->AgenteCustodiaNativo.secretos(new Properties(),new ByteArrayInputStream(new byte[16385]),JsonMapper.builder().build()));}
 @Test void tlsExactoSinDuplicadosNiAliasLegacy(){var p=new Properties();p.setProperty("x.url","jdbc:mysql://localhost:3306/lab?sslMode=VERIFY_IDENTITY&connectTimeout=3000");assertEquals(p.getProperty("x.url"),EmisorGarantiaCustodia.localUrl(p,"x"));for(String u:List.of("jdbc:mysql://localhost/lab?sslMode=VERIFY_IDENTITY&sslMode=DISABLED","jdbc:mysql://localhost/lab?sslMode=REQUIRED","jdbc:mysql://remoto/lab?sslMode=VERIFY_IDENTITY","jdbc:mysql://localhost/lab?sslMode=VERIFY_IDENTITY&useSSL=false","jdbc:mysql://localhost/lab?sslMode=VERIFY_IDENTITY&password=inseguro")){p.setProperty("x.url",u);assertThrows(IllegalArgumentException.class,()->EmisorGarantiaCustodia.localUrl(p,"x"));}}
 @Test @org.junit.jupiter.api.condition.EnabledOnOs(org.junit.jupiter.api.condition.OS.LINUX) void copiaPosixPrivadaHashYNoSobrescribePaquetes()throws Exception{var source=temp.resolve("fuente");ArchivoAgente.escribir(source,new byte[]{1,2,3});var copy=temp.resolve("copia");ArchivoAgente.copiar(source,copy);assertEquals(ArchivoAgente.huella(source),ArchivoAgente.huella(copy));assertEquals(PosixFilePermissions.fromString("r--------"),Files.getPosixFilePermissions(copy));var a=temp.resolve("a");ArchivoAgente.directorio(a);ArchivoAgente.escribir(a.resolve("dato"),new byte[]{4});var published=temp.resolve("publicado");ArchivoAgente.publicar(a,published);var b=temp.resolve("b");ArchivoAgente.directorio(b);assertThrows(FileAlreadyExistsException.class,()->ArchivoAgente.publicar(b,published));assertArrayEquals(new byte[]{4},Files.readAllBytes(published.resolve("dato")));}
 @Test @org.junit.jupiter.api.condition.EnabledOnOs(org.junit.jupiter.api.condition.OS.LINUX) void enlacesYPermisosDeEscrituraAjenosNoSeAceptan()throws Exception{var dir=temp.resolve("privado");ArchivoAgente.directorio(dir);var link=temp.resolve("enlace");Files.createSymbolicLink(link,dir);assertThrows(IOException.class,()->ArchivoAgente.raiz(link));Files.setPosixFilePermissions(dir,PosixFilePermissions.fromString("rwxrwx---"));assertThrows(IOException.class,()->ArchivoAgente.raiz(dir));}
 @Test void janitorSoloTemporalesVencidosYFueraDePaquetesPublicados()throws Exception{var old=ArchivoAgente.temporal(temp,"restauracion-ingreso-");ArchivoAgente.escribir(old.resolve("parcial"),new byte[]{1});Files.setLastModifiedTime(old,FileTime.fromMillis(1000));var current=ArchivoAgente.temporal(temp,"restauracion-ingreso-");var packet=temp.resolve("completo-historico");ArchivoAgente.directorio(packet);Files.setLastModifiedTime(packet,FileTime.fromMillis(1000));assertEquals(1,ArchivoAgente.limpiarVencidos(temp,2000));assertFalse(Files.exists(old));assertTrue(Files.exists(current));assertTrue(Files.exists(packet));assertThrows(IOException.class,()->ArchivoAgente.limpiarTemporal(packet,temp));}
 @Test void exclusionLocalYRecuperacionDelLock()throws Exception{try(var guard=new AgenteCustodiaNativo.Guardia(temp)){assertThrows(AgenteCustodiaNativo.Ocupado.class,()->new AgenteCustodiaNativo.Guardia(temp));}try(var next=new AgenteCustodiaNativo.Guardia(temp)){assertNotNull(next);}}
}